def _chk():
    ap = lambda a, b, t=1e-6: abs(a - b) <= t
    # Q1 elasticity
    assert ap(-0.08 / 0.10, -0.8) and 10 * 5000 == 50000 and 11 * 4600 == 50600 and (10 - 6) * 5000 == 20000 and (11 - 6) * 4600 == 23000
    # Q2 coupon
    assert 0.40 * 50 == 20 and 3000 * (20 - 10) - 2000 * 20 == -10000
    # Q3 CAC
    assert 1_200_000 / 6000 == 200 and 200 / 25 == 8 and 25 / 0.05 == 500 and 500 / 200 == 2.5
    n = math.log(1 - 200 * 0.05 / 25) / math.log(0.95); assert 9.9 < n < 10.0
    # Q4 credit
    assert 150 / (150 + 600) == 0.2 and ap(0.95 * 150 - 0.05 * 600, 112.5) and ap(0.8 * 150 - 0.2 * 600, 0) and ap(0.7 * 150 - 0.3 * 600, -75)
    # Q5 take rate
    assert 0.10 * 200 == 20 and ap(200 * 0.92 * 0.12, 22.08) and ap(1 - 0.10 / 0.12, 0.16667, 1e-4)
    # Q6 fraud
    assert 0.005 * 1_000_000 == 5000 and 3500 / 20000 == 0.175 and 3500 / 5000 == 0.7 and 20000 - 3500 == 16500
    assert 20000 * 2 + 16500 * 5 + (5000 - 3500) * 80 == 242_500 and 5000 * 80 == 400_000
    # Q7 newsvendor
    nd = NormalDist(); cr = 6 / 8; assert cr == 0.75 and 113 < 100 + 20 * nd.inv_cdf(0.75) < 114
    assert ap(6 / 10, 0.6) and 105 < 100 + 20 * nd.inv_cdf(0.6) < 105.2
    # Q8 churn targeting
    assert 10000 * 0.25 == 2500 and 2500 * 0.2 == 500 and 500 * 120 - 10000 * 4 == 20000 and 1000 * 0.2 * 120 - 40000 == -16000
    # Q9 price test
    assert ap(0.05 * 99, 4.95) and ap(0.038 * 129, 4.902) and ap(0.05 * 69, 3.45) and ap(0.038 * 99, 3.762) and 20000 * 0.038 == 760
    # Q10 LLM support
    assert 60000 * 5 == 300000 and 60000 * 0.2 == 12000 and 60000 * 0.4 == 24000 and 24000 * 0.15 == 3600 and 60000 - 24000 == 36000
    after = 12000 + 3600 * 5 + 36000 * 5.5 + 40000; assert after == 268000 and 300000 - after == 32000
    # Q11 ROAS
    assert 400000 / 100000 == 4 and 120000 / 100000 == 1.2 and 0.3 * 120000 - 100000 == -64000
    # Q12 surge
    assert 120 * 0.8 == 96 and 80 * 1.1 == 88 and ap(88 * 15, 1320) and ap(1320 / 800, 1.65) and 80 * 10 == 800
    # Q13 LTV cohorts
    assert 10 / 0.08 == 125 and ap(125 / 80, 1.5625) and ap(9 / 0.05, 180) and ap(180 / 30, 6.0)
    # Q14 uplift
    assert 10000 * 3 == 30000 and 0.02 * 10000 * 120 - 30000 == -6000 and ap(0.04 * 10000 * 120 - 30000, 18000)
    # Q15 fraud capacity
    assert 5000 * 0.10 == 500 and 2000 * 0.18 == 360 and 500 * 2000 / 5000 == 200 and 360 * 90 - 6000 == 26400 and 200 * 90 - 6000 == 12000 and 5000 - 2000 == 3000
    # Q16 observational elasticity
    assert ap(-1.2 * 5, -6) and ap(1.05 * 0.94, 0.987)
    # Q17 promotion
